import sys, re; from common import *
with sync_playwright() as p:
    br, ctx = launch(p, 1500, 950); pg = ctx.new_page(); wt = Watch(pg)
    pg.goto(B + "/exemples/bistro"); pg.wait_for_timeout(800)
    ok("Voir l’espace réservation client et l’espace réservation interne" in pg.inner_text("body"), "bistro: bandeau « Voir l'espace réservation client et … interne »")
    ok(pg.locator("a[href='/exemples/bistro-reservation-client']").count() >= 2 and pg.locator("a[href='/exemples/bistro-reservation-interne']").count() >= 2, "bistro: liens vers les 2 espaces")
    pg.locator(".resa-demo a", has_text="client").click(); pg.wait_for_url("**/bistro-reservation-client"); pg.wait_for_timeout(700)
    ok("Type de réservation" in pg.inner_text("body") and "Choisissez un horaire" in pg.inner_text("body"), "espace client: écran 1 (type, convives, date, horaire)")
    ok(pg.locator("#times button").count() == 5 and pg.locator("#times button.on").inner_text() == "20:00" and pg.locator("#nb").inner_text() == "4", "client: 4 convives, soir, 20:00 présélectionné comme la maquette")
    pg.click("#b-midi"); pg.wait_for_timeout(200)
    dis = pg.evaluate("[...document.querySelectorAll('#times button')].filter(b=>b.disabled).map(b=>b.dataset.t)"); ok(dis == ["13:00", "13:30"], "client: créneaux midi déjà pris barrés (13:00, 13:30)", dis)
    pg.click("#b-soir"); pg.locator("#plus").click(); pg.locator("#plus").click(); pg.wait_for_timeout(200); ok(pg.locator("#nb").inner_text() == "6", "client: + augmente les convives")
    for _ in range(2): pg.locator("#plus").click()
    ok(pg.locator("#nb").inner_text() == "8" and pg.locator("#plus").is_disabled(), "client: table limitée à 8 convives")
    pg.locator(".ty[data-k=group]").click(); pg.locator("#plus").click(); pg.wait_for_timeout(200); ok(pg.locator("#nb").inner_text() == "9", "client: groupe jusqu'à 40")
    pg.locator(".ty[data-k=table]").click(); ok(pg.locator("#nb").inner_text() == "8", "client: retour table ramène à 8")
    for _ in range(4): pg.locator("#minus").click()
    pg.locator("#times button:not([disabled])").nth(2).click()
    pg.click("#next"); pg.wait_for_timeout(300); ok(pg.locator("#s3").is_visible() and "4 convives" in pg.inner_text("#recap"), "client: étape « Vos infos » avec récapitulatif")
    pg.click("#confirm"); ok("nom" in pg.inner_text("#err3").lower(), "client: nom obligatoire")
    pg.fill("#nom", "Claire Martin"); pg.fill("#tel", "123"); pg.click("#confirm"); ok("téléphone" in pg.inner_text("#err3").lower(), "client: téléphone valide exigé")
    pg.fill("#tel", "06 12 34 56 78"); pg.fill("#mail", "pas-un-mail"); pg.click("#confirm"); ok("e-mail" in pg.inner_text("#err3").lower(), "client: e-mail invalide refusé")
    pg.fill("#mail", "claire@exemple.fr"); pg.fill("#msg", "<b>Allergie</b> noix"); pg.click("#confirm"); pg.wait_for_timeout(400)
    ok(pg.locator("#s4").is_visible() and re.match(r"RDV-[A-Z0-9]{6}", pg.inner_text("#ref")), "client: confirmation + numéro de réservation", pg.inner_text("#s4")[:120])
    pg.click("#toInt"); pg.wait_for_url("**/bistro-reservation-interne*"); pg.wait_for_timeout(800)
    t = pg.inner_text("body"); ok("Claire Martin" in t and "20 réservations" in t, "interne: la réservation du client apparaît (20 réservations)", t[300:500])
    ok(pg.locator(".blk.new").count() == 1, "interne: la nouvelle réservation est mise en évidence")
    pg.locator(".lr.new").click(); pg.wait_for_timeout(300); d = pg.inner_text("#md"); ok("Claire Martin" in d and "claire@exemple.fr" in d and "&lt;" not in d and "Allergie" in d, "interne: fiche détaillée (XSS échappé)", d[:200]); 
    ok(pg.evaluate("!document.querySelector('#md b')"), "interne: HTML saisi non interprété")
    pg.click("#mc")
    ok("2020" in "".join(ch for ch in pg.inner_text("#kpis") if ch.isdigit() or ch == "\n").replace("\n", "|") or "2020" in re.sub(r"\D", "", pg.inner_text("#kpis").split("CA estimé")[1]), "interne: chiffre d'affaires recalculé (80 couverts = 2 020 €)", pg.inner_text("#kpis"))
    pg.locator("#tabs button", has_text="Liste").click(); pg.wait_for_timeout(200); ok("Claire Martin" in pg.inner_text("#left") and pg.locator("#left tr").count() == 21, "interne: vue Liste (20 lignes)")
    pg.locator("#tabs button", has_text="Statistiques").click(); pg.wait_for_timeout(200); ok("Statistiques de réservation" in pg.inner_text("#left"), "interne: vue Statistiques")
    pg.locator("#tabs button", has_text="Statistiques").click(); pg.wait_for_timeout(200); st = pg.inner_text("#left")
    ok(re.search(r"20\s*réservations", st) and re.search(r"80\s*personnes", st), "stats: 20 réservations / 80 personnes sur la journée", st[:300])
    pg.locator("[data-tr=soir]").click(); pg.wait_for_timeout(150); ok(re.search(r"14\s*réservations", pg.inner_text("#left")), "stats: filtre Soir = 14 réservations", pg.inner_text("#left")[:260])
    pg.locator("[data-tr=matin]").click(); pg.wait_for_timeout(150); ok("Aucune réservation" in pg.inner_text("#left"), "stats: filtre Matin = aucune réservation")
    pg.locator("[data-tr=aprem]").click(); pg.wait_for_timeout(150); ok(re.search(r"6\s*réservations", pg.inner_text("#left")) and re.search(r"24\s*personnes", pg.inner_text("#left")), "stats: Midi et après-midi = 6 résas, 24 personnes")
    pg.locator("[data-tr=custom]").click(); pg.select_option("#s1", "19:00"); pg.select_option("#s2", "20:00"); pg.wait_for_timeout(150); ok(re.search(r"(\d+)\s*réservations", pg.inner_text("#left")).group(1) == "5", "stats: heures au choix 19 h-20 h = 5 résas", pg.inner_text("#left")[:300])
    pg.locator("[data-tr=all]").click(); pg.locator("[data-sp=week]").click(); pg.wait_for_timeout(200); ok("Par jour" in pg.inner_text("#left") and re.search(r"(\d+)\s*réservations", pg.inner_text("#left")), "stats: période 7 jours avec détail par jour")
    pg.locator("[data-sp=month]").click(); pg.wait_for_timeout(200); ok("Par jour" in pg.inner_text("#left"), "stats: période mois")
    pg.locator("[data-sp=custom]").click(); pg.fill("#sf", "2026-11-03"); pg.fill("#st", "2026-11-05"); pg.wait_for_timeout(300); ok("Par jour" in pg.inner_text("#left"), "stats: dates au choix")
    pg.locator("[data-sp=day]").click()
    pg.locator("#tabs button", has_text="Agenda").click(); pg.click("#prev"); pg.wait_for_timeout(300); ok("Ven. 6 nov. 2026" in pg.inner_text("#dlab"), "interne: jour précédent = vendredi")
    pg.click("#next"); pg.click("#next"); pg.click("#next"); pg.wait_for_timeout(300); ok("Mar. 10 nov. 2026" in pg.inner_text("#dlab"), "interne: le dimanche puis lundi (fermé) sont franchis proprement", pg.inner_text("#dlab"))
    pg.wait_for_timeout(200)
    pg.goto(B + "/exemples/bistro-reservation-interne"); pg.wait_for_timeout(600)
    pg.click("#add"); pg.fill("#fn", "M. Durand"); pg.select_option("#fh", "12:00"); pg.fill("#fp", "3"); pg.click("#fs"); pg.wait_for_timeout(400); ok("M. Durand" in pg.inner_text("#left"), "interne: « Nouvelle réservation » ajoute au planning")
    pg.locator(".blk", has_text="M. Durand").click(); pg.click("#mx"); pg.wait_for_timeout(300); ok("M. Durand" not in pg.inner_text("#left"), "interne: annuler libère la table")
    pg.click("#bell"); ok("Nouvelle réservation en ligne" in pg.inner_text("#pop"), "interne: notification de réservation en ligne")
    with pg.expect_download() as dl: pg.click("#exp")
    ok(dl.value.suggested_filename.startswith("reservations-"), "interne: export CSV")
    pg.locator("aside .nv", has_text="Clients").click(); ok("démonstration" in pg.inner_text("#toast"), "interne: menus non disponibles: message clair")
    # créneau rempli côté client après réservations
    pg.goto(B + "/exemples/bistro-reservation-client"); pg.wait_for_timeout(500)
    for i in range(8):
        pg.evaluate("""() => { const k='bistro-demo-resa-v1', o=JSON.parse(localStorage.getItem(k)); o.res.push({id:'z'+Math.random(),iso:'2026-11-07',t:'20:00',n:8,nom:'X',kind:'table'}); localStorage.setItem(k, JSON.stringify(o)); }""")
    pg.reload(); pg.wait_for_timeout(500); dis = pg.evaluate("[...document.querySelectorAll('#times button')].filter(b=>b.disabled).map(b=>b.dataset.t)"); ok("20:00" in dis, "client: le créneau se remplit quand le restaurant est complet", dis)
    # lundi / dimanche
    pg.select_option("#date", "2026-11-08"); pg.wait_for_timeout(200); ok(pg.locator("#b-soir").is_disabled(), "client: dimanche = midi uniquement")
    ok(pg.locator("#date option[value='2026-11-09']").count() == 0, "client: lundi absent des dates (fermé)")
    # mobile
    pg.set_viewport_size({"width": 390, "height": 800}); pg.goto(B + "/exemples/bistro-reservation-client"); pg.wait_for_timeout(500)
    ok(pg.evaluate("document.documentElement.scrollWidth <= innerWidth + 1"), "client (mobile): pas de débordement horizontal")
    pg.goto(B + "/exemples/bistro-reservation-interne"); pg.wait_for_timeout(500); ok(pg.evaluate("document.documentElement.scrollWidth <= innerWidth + 1"), "interne (mobile): pas de débordement horizontal", pg.evaluate("document.documentElement.scrollWidth"))
    errs = [e for e in wt.take() if "fonts.g" not in e]; ok(not errs, "aucune erreur JS/console/CSP", errs)
    br.close()
finish(sys.argv[1])
